INSERT INTO "fault_location_rules" ("issue_type", "location", "signal", "expected_sign", "meaning") VALUES ('leak', 'inlet_flow', 'q_in', 'slightly_up', 'Leak increases line draw at inlet.');
INSERT INTO "fault_location_rules" ("issue_type", "location", "signal", "expected_sign", "meaning") VALUES ('leak', 'outlet_flow', 'q_out', 'down', 'Less flow reaches destination.');
INSERT INTO "fault_location_rules" ("issue_type", "location", "signal", "expected_sign", "meaning") VALUES ('leak', 'paired_flows', 'q_in-q_out', 'up', 'Flow gap estimates leak flow.');
INSERT INTO "fault_location_rules" ("issue_type", "location", "signal", "expected_sign", "meaning") VALUES ('leak', 'pump_discharge_pressure', 'pressure', 'down', 'Modeled discharge pressure falls slightly.');
INSERT INTO "fault_location_rules" ("issue_type", "location", "signal", "expected_sign", "meaning") VALUES ('blockage', 'pump_discharge_pressure', 'pressure', 'up', 'Pressure rises upstream of pipe restriction.');
INSERT INTO "fault_location_rules" ("issue_type", "location", "signal", "expected_sign", "meaning") VALUES ('blockage', 'pipe_across_taps', 'pressure_drop', 'up', 'Pressure loss across restricted pipe increases.');
INSERT INTO "fault_location_rules" ("issue_type", "location", "signal", "expected_sign", "meaning") VALUES ('pump_degradation', 'pump_discharge_pressure', 'pressure', 'down', 'Reduced pump head lowers discharge pressure.');
INSERT INTO "fault_location_rules" ("issue_type", "location", "signal", "expected_sign", "meaning") VALUES ('valve_partial', 'valve_across_taps', 'pressure_drop', 'up', 'Pressure loss across partially closed valve increases.');
INSERT INTO "fault_location_rules" ("issue_type", "location", "signal", "expected_sign", "meaning") VALUES ('valve_partial', 'pipe_pressure_drop', 'pressure_drop', 'down', 'Lower line flow reduces pipe friction loss.');
INSERT INTO "fault_location_rules" ("issue_type", "location", "signal", "expected_sign", "meaning") VALUES ('sensor_fault', 'faulty_sensor', 'measurement_error', 'depends_on_fault', 'Process truth is unchanged; reading alone is faulty.');
INSERT INTO "fault_location_rules" ("issue_type", "location", "signal", "expected_sign", "meaning") VALUES ('sensor_fault', 'paired_flows', 'apparent_flow_gap', 'may_be_nonzero', 'Stuck inlet sensor can mimic a leak in measured data.');
INSERT INTO "fault_location_rules" ("issue_type", "location", "signal", "expected_sign", "meaning") VALUES ('compound_fault', 'paired_flows', 'q_in-q_out', 'up', 'Concurrent leak and blockage produce a flow gap.');
INSERT INTO "fault_location_rules" ("issue_type", "location", "signal", "expected_sign", "meaning") VALUES ('compound_fault', 'pipe_across_taps', 'pressure_drop', 'up', 'Concurrent blockage increases pipe pressure loss.');
