PRAGMA foreign_keys = ON;
PRAGMA defer_foreign_keys = ON;
BEGIN TRANSACTION;
CREATE TABLE "facilities" (
  "facility_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "lifecycle_state" TEXT NOT NULL,
  CHECK ("lifecycle_state" IN ('planned', 'active', 'maintenance', 'out_of_service', 'retired')),
  PRIMARY KEY ("facility_id")
);
CREATE TABLE "operating_modes" (
  "operating_mode_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "effective_from_utc" TEXT NOT NULL,
  "effective_to_utc" TEXT,
  PRIMARY KEY ("operating_mode_id")
);
CREATE TABLE "tanks" (
  "tank_id" TEXT NOT NULL,
  "facility_id" TEXT NOT NULL,
  "tank_role" TEXT NOT NULL,
  "capacity_m3" REAL NOT NULL,
  "area_m2" REAL NOT NULL,
  "initial_volume_m3" REAL NOT NULL,
  "lifecycle_state" TEXT NOT NULL,
  CHECK ("lifecycle_state" IN ('planned', 'active', 'maintenance', 'out_of_service', 'retired')),
  PRIMARY KEY ("tank_id"),
  FOREIGN KEY ("facility_id") REFERENCES "facilities" ("facility_id")
);
CREATE TABLE "lines" (
  "line_id" TEXT NOT NULL,
  "facility_id" TEXT NOT NULL,
  "source_tank_id" TEXT NOT NULL,
  "destination_tank_id" TEXT NOT NULL,
  "pump_id" TEXT NOT NULL,
  "valve_id" TEXT NOT NULL,
  "pipe_id" TEXT NOT NULL,
  PRIMARY KEY ("line_id"),
  FOREIGN KEY ("facility_id") REFERENCES "facilities" ("facility_id"),
  FOREIGN KEY ("source_tank_id") REFERENCES "tanks" ("tank_id"),
  FOREIGN KEY ("destination_tank_id") REFERENCES "tanks" ("tank_id"),
  FOREIGN KEY ("pump_id") REFERENCES "pumps" ("pump_id"),
  FOREIGN KEY ("valve_id") REFERENCES "valves" ("valve_id"),
  FOREIGN KEY ("pipe_id") REFERENCES "pipes" ("pipe_id")
);
CREATE TABLE "pumps" (
  "pump_id" TEXT NOT NULL,
  "facility_id" TEXT NOT NULL,
  "line_id" TEXT NOT NULL,
  "nominal_flow_m3_h" REAL NOT NULL,
  "shutoff_head_m" REAL NOT NULL,
  "lifecycle_state" TEXT NOT NULL,
  CHECK ("lifecycle_state" IN ('planned', 'active', 'maintenance', 'out_of_service', 'retired')),
  PRIMARY KEY ("pump_id"),
  FOREIGN KEY ("facility_id") REFERENCES "facilities" ("facility_id"),
  FOREIGN KEY ("line_id") REFERENCES "lines" ("line_id")
);
CREATE TABLE "valves" (
  "valve_id" TEXT NOT NULL,
  "facility_id" TEXT NOT NULL,
  "line_id" TEXT NOT NULL,
  "normal_opening_pct" REAL NOT NULL,
  "sequence_order" INTEGER NOT NULL,
  "resistance_k" REAL NOT NULL,
  "lifecycle_state" TEXT NOT NULL,
  CHECK ("lifecycle_state" IN ('planned', 'active', 'maintenance', 'out_of_service', 'retired')),
  PRIMARY KEY ("valve_id"),
  FOREIGN KEY ("facility_id") REFERENCES "facilities" ("facility_id"),
  FOREIGN KEY ("line_id") REFERENCES "lines" ("line_id"),
  UNIQUE ("line_id", "sequence_order")
);
CREATE TABLE "pipes" (
  "pipe_id" TEXT NOT NULL,
  "facility_id" TEXT NOT NULL,
  "line_id" TEXT,
  "from_node_id" TEXT NOT NULL,
  "to_node_id" TEXT NOT NULL,
  "resistance_k" REAL NOT NULL,
  "edge_role" TEXT NOT NULL,
  "sequence_order" INTEGER,
  "lifecycle_state" TEXT NOT NULL,
  CHECK ("lifecycle_state" IN ('planned', 'active', 'maintenance', 'out_of_service', 'retired')),
  PRIMARY KEY ("pipe_id"),
  FOREIGN KEY ("facility_id") REFERENCES "facilities" ("facility_id"),
  FOREIGN KEY ("line_id") REFERENCES "lines" ("line_id"),
  UNIQUE ("line_id", "sequence_order")
);
CREATE TABLE "line_valves" (
  "line_id" TEXT NOT NULL,
  "valve_id" TEXT NOT NULL,
  "sequence_order" INTEGER NOT NULL,
  PRIMARY KEY ("line_id", "valve_id"),
  FOREIGN KEY ("line_id") REFERENCES "lines" ("line_id"),
  FOREIGN KEY ("valve_id") REFERENCES "valves" ("valve_id"),
  UNIQUE ("line_id", "sequence_order")
);
CREATE TABLE "line_pipes" (
  "line_id" TEXT NOT NULL,
  "pipe_id" TEXT NOT NULL,
  "sequence_order" INTEGER NOT NULL,
  PRIMARY KEY ("line_id", "pipe_id"),
  FOREIGN KEY ("line_id") REFERENCES "lines" ("line_id"),
  FOREIGN KEY ("pipe_id") REFERENCES "pipes" ("pipe_id"),
  UNIQUE ("line_id", "sequence_order")
);
CREATE TABLE "sensors" (
  "sensor_id" TEXT NOT NULL,
  "facility_id" TEXT NOT NULL,
  "line_id" TEXT,
  "entity_type" TEXT NOT NULL,
  "entity_id" TEXT,
  "node_id" TEXT,
  "pipe_id" TEXT,
  "position" TEXT NOT NULL,
  "metric" TEXT NOT NULL,
  "unit" TEXT NOT NULL,
  "initial_level_m" TEXT,
  CHECK (substr("sensor_id",1,4)='SNS-' AND length("sensor_id")>=7 AND substr("sensor_id",5) NOT GLOB '*[^0-9]*'),
  PRIMARY KEY ("sensor_id"),
  FOREIGN KEY ("facility_id") REFERENCES "facilities" ("facility_id"),
  FOREIGN KEY ("line_id") REFERENCES "lines" ("line_id"),
  FOREIGN KEY ("pipe_id") REFERENCES "pipes" ("pipe_id")
);
CREATE TABLE "valve_mode_states" (
  "valve_id" TEXT NOT NULL,
  "operating_mode_id" TEXT NOT NULL,
  "state" TEXT NOT NULL,
  "effective_from_utc" TEXT NOT NULL,
  "effective_to_utc" TEXT,
  PRIMARY KEY ("valve_id", "operating_mode_id", "effective_from_utc"),
  FOREIGN KEY ("valve_id") REFERENCES "valves" ("valve_id"),
  FOREIGN KEY ("operating_mode_id") REFERENCES "operating_modes" ("operating_mode_id")
);
CREATE TABLE "simulation_runs" (
  "sim_run_id" TEXT NOT NULL,
  "facility_id" TEXT NOT NULL,
  "seed" INTEGER NOT NULL,
  "config_hash" TEXT NOT NULL,
  "config_json" TEXT NOT NULL,
  "started_at_utc" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  PRIMARY KEY ("sim_run_id"),
  FOREIGN KEY ("facility_id") REFERENCES "facilities" ("facility_id")
);
CREATE TABLE "telemetry" (
  "telemetry_id" TEXT NOT NULL,
  "timestamp_utc" TEXT NOT NULL,
  "sim_run_id" TEXT NOT NULL,
  "operating_mode_id" TEXT NOT NULL,
  "facility_id" TEXT NOT NULL,
  "line_id" TEXT,
  "sensor_id" TEXT NOT NULL,
  "entity_id" TEXT,
  "node_id" TEXT,
  "pipe_id" TEXT,
  "position" TEXT NOT NULL,
  "metric" TEXT NOT NULL,
  "value" REAL NOT NULL,
  "unit" TEXT NOT NULL,
  "quality_flag" TEXT NOT NULL,
  PRIMARY KEY ("telemetry_id"),
  FOREIGN KEY ("sim_run_id") REFERENCES "simulation_runs" ("sim_run_id"),
  FOREIGN KEY ("operating_mode_id") REFERENCES "operating_modes" ("operating_mode_id"),
  FOREIGN KEY ("facility_id") REFERENCES "facilities" ("facility_id"),
  FOREIGN KEY ("line_id") REFERENCES "lines" ("line_id"),
  FOREIGN KEY ("sensor_id") REFERENCES "sensors" ("sensor_id")
);
CREATE TABLE "process_truth" (
  "telemetry_id" TEXT NOT NULL,
  "timestamp_utc" TEXT NOT NULL,
  "sim_run_id" TEXT NOT NULL,
  "sensor_id" TEXT NOT NULL,
  "true_value" REAL NOT NULL,
  "noise_added" REAL NOT NULL,
  "noise_sigma" REAL NOT NULL,
  PRIMARY KEY ("telemetry_id"),
  FOREIGN KEY ("telemetry_id") REFERENCES "telemetry" ("telemetry_id"),
  FOREIGN KEY ("sim_run_id") REFERENCES "simulation_runs" ("sim_run_id"),
  FOREIGN KEY ("sensor_id") REFERENCES "sensors" ("sensor_id")
);
CREATE TABLE "ground_truth" (
  "scenario_id" TEXT NOT NULL,
  "sim_run_id" TEXT NOT NULL,
  "issue_type" TEXT NOT NULL,
  "entity_id" TEXT NOT NULL,
  "start_ts" TEXT NOT NULL,
  "end_ts" TEXT NOT NULL,
  "is_process_fault" TEXT NOT NULL,
  "fault_params_json" TEXT NOT NULL,
  "primary_signal" TEXT NOT NULL,
  "evidence_sensor_id" TEXT NOT NULL,
  "evidence_telemetry_id" TEXT NOT NULL,
  "effect_abs" REAL NOT NULL,
  "effect_relative" REAL NOT NULL,
  "true_effect_abs" REAL NOT NULL,
  "measured_effect_abs" REAL NOT NULL,
  "noise_sigma_single_sample" REAL NOT NULL,
  "noise_sigma_window" REAL NOT NULL,
  "sample_count" INTEGER NOT NULL,
  "detectability_sigma" INTEGER NOT NULL,
  "detectability_rule" TEXT NOT NULL,
  "detectable" TEXT NOT NULL,
  "alarm_detected" TEXT NOT NULL,
  "expected_sign_by_location_json" TEXT NOT NULL,
  PRIMARY KEY ("scenario_id"),
  FOREIGN KEY ("sim_run_id") REFERENCES "simulation_runs" ("sim_run_id"),
  FOREIGN KEY ("evidence_sensor_id") REFERENCES "sensors" ("sensor_id"),
  FOREIGN KEY ("evidence_telemetry_id") REFERENCES "telemetry" ("telemetry_id")
);
CREATE TABLE "equipment_events" (
  "event_id" TEXT NOT NULL,
  "event_ts" TEXT NOT NULL,
  "entity_type" TEXT NOT NULL,
  "entity_id" TEXT NOT NULL,
  "event_type" TEXT NOT NULL,
  "from_state" TEXT NOT NULL,
  "to_state" TEXT NOT NULL,
  "sim_run_id" TEXT NOT NULL,
  "cause_scenario_id" TEXT NOT NULL,
  PRIMARY KEY ("event_id"),
  FOREIGN KEY ("sim_run_id") REFERENCES "simulation_runs" ("sim_run_id"),
  FOREIGN KEY ("cause_scenario_id") REFERENCES "ground_truth" ("scenario_id")
);
CREATE TABLE "alarms" (
  "alarm_id" TEXT NOT NULL,
  "timestamp_utc" TEXT NOT NULL,
  "sim_run_id" TEXT NOT NULL,
  "facility_id" TEXT NOT NULL,
  "line_id" TEXT,
  "alarm_type" TEXT NOT NULL,
  "primary_signal" TEXT NOT NULL,
  "trigger_telemetry_id" TEXT NOT NULL,
  "window_effect_abs" REAL NOT NULL,
  "noise_sigma_window" REAL NOT NULL,
  "detector_rule" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  PRIMARY KEY ("alarm_id"),
  FOREIGN KEY ("sim_run_id") REFERENCES "simulation_runs" ("sim_run_id"),
  FOREIGN KEY ("facility_id") REFERENCES "facilities" ("facility_id"),
  FOREIGN KEY ("line_id") REFERENCES "lines" ("line_id"),
  FOREIGN KEY ("trigger_telemetry_id") REFERENCES "telemetry" ("telemetry_id")
);
CREATE TABLE "network_balance" (
  "timestamp_utc" TEXT NOT NULL,
  "sim_run_id" TEXT NOT NULL,
  "facility_id" TEXT NOT NULL,
  "true_supply_minus_leak_minus_storage_m3_h" REAL NOT NULL,
  "measured_supply_minus_leak_minus_storage_m3_h" REAL NOT NULL,
  "q_in_true_m3_h" REAL NOT NULL,
  "q_out_true_m3_h" REAL NOT NULL,
  "q_leak_true_m3_h" REAL NOT NULL,
  "storage_rate_m3_h" REAL NOT NULL,
  "source_level_m" REAL NOT NULL,
  "destination_level_m" REAL NOT NULL,
  PRIMARY KEY ("timestamp_utc", "sim_run_id", "facility_id"),
  FOREIGN KEY ("sim_run_id") REFERENCES "simulation_runs" ("sim_run_id"),
  FOREIGN KEY ("facility_id") REFERENCES "facilities" ("facility_id")
);
CREATE TABLE "fault_location_rules" (
  "issue_type" TEXT NOT NULL,
  "location" TEXT NOT NULL,
  "signal" TEXT NOT NULL,
  "expected_sign" TEXT NOT NULL,
  "meaning" TEXT NOT NULL
);
CREATE TABLE "negative_fixtures" (
  "case_id" TEXT NOT NULL,
  "case" TEXT NOT NULL,
  "entity" TEXT NOT NULL,
  "observed" TEXT NOT NULL,
  "ground_truth_issue" TEXT NOT NULL,
  "is_process_fault" TEXT NOT NULL,
  "validator_rule" TEXT NOT NULL,
  "validator_flagged" TEXT NOT NULL,
  PRIMARY KEY ("case_id")
);
CREATE TABLE "boundary_fixtures" (
  "boundary_id" TEXT NOT NULL,
  "case" TEXT NOT NULL,
  "metric" TEXT NOT NULL,
  "value" REAL NOT NULL,
  "unit" TEXT NOT NULL,
  "lower_limit" REAL NOT NULL,
  "upper_limit" REAL NOT NULL,
  "expected_validator_result" TEXT NOT NULL,
  "scenario_coverage" TEXT NOT NULL,
  "validator_passed" TEXT NOT NULL,
  PRIMARY KEY ("boundary_id")
);
COMMIT;
